def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = [[False] * w for _ in range(h)]
    holes = []

    # Find enclosed 4-connected zero regions.
    for sr in range(h):
        for sc in range(w):
            if grid[sr][sc] != 0 or seen[sr][sc]:
                continue
            seen[sr][sc] = True
            q = deque([(sr, sc)])
            cells = []
            edge = False
            while q:
                r, c = q.popleft()
                cells.append((r, c))
                if r == 0 or c == 0 or r == h - 1 or c == w - 1:
                    edge = True
                for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nr, nc = r + dr, c + dc
                    if (0 <= nr < h and 0 <= nc < w and
                            grid[nr][nc] == 0 and not seen[nr][nc]):
                        seen[nr][nc] = True
                        q.append((nr, nc))
            if not edge:
                holes.append(cells)

    # The enclosing 1-cells, and the zero cells immediately inside their outline.
    active_ones = set()
    for cells in holes:
        for r, c in cells:
            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                nr, nc = r + dr, c + dc
                if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 1:
                    active_ones.add((nr, nc))
        for r, c in cells:
            if any((r + dr, c + dc) in active_ones
                   for dr in (-1, 0, 1) for dc in (-1, 0, 1)):
                out[r][c] = 3

    # Color the exterior one-cell halo of the enclosing outlines.
    for r, c in active_ones:
        for dr in (-1, 0, 1):
            for dc in (-1, 0, 1):
                nr, nc = r + dr, c + dc
                if (0 <= nr < h and 0 <= nc < w and
                        grid[nr][nc] == 0 and seen[nr][nc]):
                    out[nr][nc] = 2

    return out
