from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Label 4-connected components of 1-cells.
    comp = [[-1] * w for _ in range(h)]
    components = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 1 or comp[r][c] != -1:
                continue
            k = len(components)
            cells = []
            comp[r][c] = k
            q = deque([(r, c)])
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and
                            grid[ny][nx] == 1 and comp[ny][nx] == -1):
                        comp[ny][nx] = k
                        q.append((ny, nx))
            components.append(cells)

    # Label 4-connected zero regions; regions that don't touch the edge are holes.
    zid = [[-1] * w for _ in range(h)]
    regions = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 or zid[r][c] != -1:
                continue
            k = len(regions)
            cells = []
            touches_edge = False
            zid[r][c] = k
            q = deque([(r, c)])
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                if y == 0 or y == h - 1 or x == 0 or x == w - 1:
                    touches_edge = True
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and
                            grid[ny][nx] == 0 and zid[ny][nx] == -1):
                        zid[ny][nx] = k
                        q.append((ny, nx))
            regions.append((cells, touches_edge))

    # Determine which line components border enclosed zero regions.
    bordering = [set() for _ in regions]
    for r in range(h):
        for c in range(w):
            z = zid[r][c]
            if z < 0:
                continue
            for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                ny, nx = r + dy, c + dx
                if 0 <= ny < h and 0 <= nx < w and comp[ny][nx] >= 0:
                    bordering[z].add(comp[ny][nx])

    holes = {z for z, (_, edge) in enumerate(regions) if not edge}
    active = set()
    for z in holes:
        active.update(bordering[z])

    # Color the inner one-cell rim of each hole with 3.
    for z in holes:
        for r, c in regions[z][0]:
            if any(
                0 <= r + dy < h and 0 <= c + dx < w and
                comp[r + dy][c + dx] in bordering[z]
                for dy in (-1, 0, 1) for dx in (-1, 0, 1)
            ):
                out[r][c] = 3

    # Color the exterior one-cell halo around each entire enclosing component.
    for k in active:
        for r, c in components[k]:
            for dy in (-1, 0, 1):
                for dx in (-1, 0, 1):
                    nr, nc = r + dy, c + dx
                    if not (0 <= nr < h and 0 <= nc < w):
                        continue
                    if grid[nr][nc] != 0:
                        continue
                    z = zid[nr][nc]
                    if z >= 0 and regions[z][1]:
                        out[nr][nc] = 2

    return out
